"""docs/accuracy.md is generated by scripts/accuracy.py from the model."""
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def test_accuracy_page_is_current():
    # a model or catalogue change that moves a prediction must regenerate
    # the page, or it would publish errors the model no longer makes
    r = subprocess.run([sys.executable, str(ROOT / "scripts" / "accuracy.py"), "--check"],
                       capture_output=True, text=True)
    assert r.returncode == 0, r.stderr
